-        if (v[3]) status[StatusError] = 1'b1;
+        if (v[1]) status[StatusDone]      = 1'b1;
+        if (v[3]) status[StatusError]     = 1'b1;
+        if (v[5]) status[StatusChunkDone] = 1'b1;
       end
       // Note: sha2_digest_valid is not a completion event
       // v[12]
