rtl_diff:
commit f0ce706f96eab7ce0194abb86e6ef9f10cc72187
Author: Neeraj Upasani <neeraj@opentitan.org>
Date:   Sat Sep 16 00:14:36 2023 -0700

    [gpio] Add snapshot functionality

            Existing strap_en signal driven by pwrmgr is used as the sampling pulse

            Sample pulse is a single cycle of io_div4 clk and must toggle only once (assertion)

            Both driver (pwrmgr) & receiver clk (gpio) are in the domain (io_div4). No async crossings

    Signed-off-by: Neeraj Upasani <neeraj@opentitan.org>

diff --git a/hw/ip/gpio/rtl/gpio.sv b/hw/ip/gpio/rtl/gpio.sv
index 72f14e0de8..e42a1286a5 100644
--- a/hw/ip/gpio/rtl/gpio.sv
+++ b/hw/ip/gpio/rtl/gpio.sv
@@ -7,15 +7,21 @@
 `include "prim_assert.sv"

 module gpio
+  import gpio_pkg::*;
   import gpio_reg_pkg::*;
 #(
   parameter logic [NumAlerts-1:0] AlertAsyncOn = {NumAlerts{1'b1}},
+  parameter bit GpioAsHwStrapsEn = 1,
   // This parameter instantiates 2-stage synchronizers on all GPIO inputs.
   parameter bit GpioAsyncOn = 1
 ) (
   input clk_i,
   input rst_ni,

+  // Strap sampling trigger and broadcast output
+  input strap_en_i,
+  output gpio_straps_t sampled_straps_o,
+
   // Bus interface
   input  tlul_pkg::tl_h2d_t tl_i,
   output tlul_pkg::tl_d2h_t tl_o,
@@ -58,6 +64,43 @@ module gpio
     );
   end

+
+
+  if (GpioAsHwStrapsEn) begin : gen_strap_sample
+    // sample at gpio inputs at strap_en_i signal pulse.
+    logic strap_en;
+    prim_flop_2sync #(
+      .Width(1)
+    ) u_prim_flop_2sync (
+      .clk_i,
+      .rst_ni,
+      .d_i(strap_en_i),
+      .q_o(strap_en)
+    );
+    // we guarantee here by design that this will always be done exactly once per reset cycle.
+    logic sample_trigger;
+    assign sample_trigger                    = strap_en && !reg2hw.hw_straps_data_in_valid.q;
+    assign hw2reg.hw_straps_data_in_valid.de = sample_trigger;
+    assign hw2reg.hw_straps_data_in_valid.d  = 1'b1;
+    assign hw2reg.hw_straps_data_in.de       = sample_trigger;
+    assign hw2reg.hw_straps_data_in.d        = data_in_d;
+    assign sampled_straps_o.data             = reg2hw.hw_straps_data_in.q;
