@@ -38,6 +38,9 @@ interface keymgr_dpe_if(input clk, input rst_n);
   // connect EDN for assertion check
   wire edn_clk, edn_rst_n, edn_req, edn_ack;

+  // connect to PRNG to track PRNG updates for EDN assertion
