commit 3deb27b2d7f9370f8eae344962d360c8960c0cbb
Author: Adrian Lees <a.lees@lowrisc.org>
Date:   Wed Nov 1 19:09:10 2023 +0000

    [dma] Fixes for abort handling

    Clear the CONTROL.abort bit once the abort has been processed,
    otherwise software must explicitly reset that WO bit before it
    can clear STATUS.aborted.
    Reduce the number of outstanding TL-UL requests to one since the
    DMA controller cannot issue overlapped requests, and aborting
    mid-transaction otherwise causes spurious assertions in
    tlul_adapter_host.

    Signed-off-by: Adrian Lees <a.lees@lowrisc.org>

diff --git a/hw/ip/dma/rtl/dma.sv b/hw/ip/dma/rtl/dma.sv
index a102ab0a45..04f5b9da95 100644
--- a/hw/ip/dma/rtl/dma.sv
+++ b/hw/ip/dma/rtl/dma.sv
@@ -196,6 +196,7 @@ module dma

   // Adapter from the DMA to Host
   tlul_adapter_host #(
+    .MAX_REQS(NUM_MAX_OUTSTANDING_REQS),
     .EnableDataIntgGen(EnableDataIntgGen)
   ) u_dma_host_tlul_host (
     .clk_i          ( gated_clk                        ),
@@ -221,6 +222,7 @@ module dma

   // Adapter from the DMA to the CTN
   tlul_adapter_host #(
+    .MAX_REQS(NUM_MAX_OUTSTANDING_REQS),
     .EnableDataIntgGen(EnableDataIntgGen)
   ) u_dma_ctn_tlul_host (
     .clk_i          ( gated_clk                        ),
@@ -1297,6 +1299,10 @@ module dma
     hw2reg.status.aborted.de = cfg_abort_en && (ctrl_state_d == DmaIdle);
     hw2reg.status.aborted.d  = 1'b1;

+    // Clear the control.abort bit once we have handled the abort request
+    hw2reg.control.abort.de = hw2reg.status.aborted.de;
+    hw2reg.control.abort.d  = 1'b0;
+
     // interrupt management
     hw2reg.intr_state.dma_done.de = reg2hw.status.done.q | test_done_interrupt;
     hw2reg.intr_state.dma_done.d  = 1'b1;
diff --git a/hw/ip/dma/rtl/dma_pkg.sv b/hw/ip/dma/rtl/dma_pkg.sv
