commit 376c792a963f382f63dc859302111c72bb7e3f1c
Author: Adrian Lees <a.lees@lowrisc.org>
Date:   Fri Oct 27 18:16:59 2023 +0100

    [dma] SHA2 expects big endian data

    SHA2 module expects `data` and `mask` to be populated from the
    Most Significant lanes downwards. Must therefore swap within the
    RTL rather than trying to make the test bench prediction match
    unswapped data (which failed for non-4n transfers).

    Signed-off-by: Adrian Lees <a.lees@lowrisc.org>

diff --git a/hw/ip/dma/rtl/dma.sv b/hw/ip/dma/rtl/dma.sv
index 5b888bcd88..15674e8878 100644
--- a/hw/ip/dma/rtl/dma.sv
+++ b/hw/ip/dma/rtl/dma.sv
@@ -1079,9 +1079,11 @@ module dma

   // Mux the data for the SHA2 engine. When capturing the data we
   // can use the data from the bus, otherwise the captured data from the flop
-  assign sha2_data.data = capture_return_data? read_return_data_d :
-                                               read_return_data_q;
-  assign sha2_data.mask = req_dst_be_q;
+  //
+  // Note: the SHA2 logic expects the `data` and `mask` fields to be populated from the MSBs down.
+  assign sha2_data.data = {<<8{capture_return_data ? read_return_data_d :
+                                                     read_return_data_q}};
+  assign sha2_data.mask = {<<1{req_dst_be_q}};

   // Interrupt logic
   logic test_done_interrupt;

