     dma_reg2hw_chunk_data_size_reg_t chunk_data_size; // [1499:1467]
     dma_reg2hw_transfer_width_reg_t transfer_width; // [1466:1464]
@@ -368,7 +368,7 @@ package dma_reg_pkg;
