dv_diff:
commit e7ce9718ebe01905c9cf475b6387b5f88e96eb82
Author: Greg Chadwick <gac@lowrisc.org>
Date:   Tue Jun 4 20:36:46 2024 +0100

    [uart] Add new tx_empty interrupt

    This new interrupt is a true empty interrupt. It is a status type and is
    raised when the TX FIFO is empty.

    Signed-off-by: Greg Chadwick <gac@lowrisc.org>

diff --git a/hw/ip/uart/dv/env/seq_lib/uart_intr_vseq.sv b/hw/ip/uart/dv/env/seq_lib/uart_intr_vseq.sv
index b17e7a0292..ebc7552557 100644
--- a/hw/ip/uart/dv/env/seq_lib/uart_intr_vseq.sv
+++ b/hw/ip/uart/dv/env/seq_lib/uart_intr_vseq.sv
@@ -41,7 +41,7 @@ class uart_intr_vseq extends uart_base_vseq;
         // tx may have unfinished transaction
         spinwait_txidle();
         dut_shutdown();
-        csr_wr(.ptr(ral.intr_state), .value('hff));
+        csr_wr(.ptr(ral.intr_state), .value((1 << NumUartIntr) - 1));
       end
       `uvm_info(`gfn, $sformatf("finished run %0d/%0d", i, num_trans), UVM_LOW)
     end
@@ -86,6 +86,39 @@ class uart_intr_vseq extends uart_base_vseq;
         cfg.m_uart_agent_cfg.vif.wait_for_tx_idle();
       end

+      TxEmpty: begin
+        if (!en_tx) return;
+        // Interrupt should begin high, before we push anything to the TX FIFO
+        check_one_intr(.uart_intr(uart_intr), .exp(1));
+        // Write a single byte to the TX FIFO which will immediately begin transmission
+        drive_tx_bytes(.num_bytes(1));
+        // Need a brief delay while the data byte is popped and the interrupt returns high
+        cfg.clk_rst_vif.wait_clks(1);
+        // Interrupt should now be high as TX FIFO will be empty (but TX of first byte on-going)
+        check_one_intr(.uart_intr(uart_intr), .exp(1));
+        // Drive a second byte
+        drive_tx_bytes(.num_bytes(1));
+        // Interrupt should now be low as second byte will be in TX FIFO whilst TX of first byte is
+        // ongoing
+        check_one_intr(.uart_intr(uart_intr), .exp(0));
+        // wait until TX FIFO empties again
+        csr_spinwait(.ptr(ral.fifo_status.txlvl),
+                     .exp_data(0),
+                     .compare_op(CompareOpEq));
+        // Interrupt should now be high
+        check_one_intr(.uart_intr(uart_intr), .exp(1));
+        cfg.m_uart_agent_cfg.vif.wait_for_tx_idle();
+        // interrupt should remain asserted whilst FIFO is empty, writes to intr_state to clear have
+        // no effect
+        csr_wr(.ptr(ral.intr_state), .value(1 << uart_intr));
+        check_one_intr(.uart_intr(uart_intr), .exp(1));
+        // check interrupt clears when FIFO is non-empty again (2 bytes needed as first will be
+        // popped for transmission).
+        drive_tx_bytes(.num_bytes(2));
+        check_one_intr(.uart_intr(uart_intr), .exp(0));
+        cfg.m_uart_agent_cfg.vif.wait_for_tx_idle();
+      end
+
       RxWatermark: begin
         int level = ral.fifo_ctrl.rxilvl.get_mirrored_value();
         int watermark_bytes = get_rx_watermark_bytes_by_level(level);
@@ -144,11 +177,12 @@ class uart_intr_vseq extends uart_base_vseq;
         drive_rx_bytes(.num_bytes(1));
         // clear rx fifo and interrupts triggered by above driving
         clear_fifos(.clear_tx_fifo(0), .clear_rx_fifo(1));
-        csr_wr(.ptr(ral.intr_state), .value('hff));
+        csr_wr(.ptr(ral.intr_state), .value((1 << NumUartIntr) - 1));

         // Don't attempt to predict Tx/Rx watermark when testing RxBreakErr so we don't need to
         // predict TX/RX FIFO levels for this test.
         exp_intr_state_mask[TxWatermark] = 1'b0;
+        exp_intr_state_mask[TxEmpty] = 1'b0;
         exp_intr_state_mask[RxWatermark] = 1'b0;

         fork
@@ -215,11 +249,11 @@ class uart_intr_vseq extends uart_base_vseq;
         check_one_intr(.uart_intr(uart_intr), .exp(0));
         wait_for_baud_clock_cycles(2);
         check_one_intr(.uart_intr(uart_intr), .exp(en_rx & en_timeout));
-        csr_wr(.ptr(ral.intr_state), .value('hff));
+        csr_wr(.ptr(ral.intr_state), .value((1 << NumUartIntr) - 1));
         // expect timeout again since no fifo activity
         wait_for_baud_clock_cycles(timeout_val + 1);
         check_one_intr(.uart_intr(uart_intr), .exp(en_rx & en_timeout));
-        csr_wr(.ptr(ral.intr_state), .value('hff));
+        csr_wr(.ptr(ral.intr_state), .value((1 << NumUartIntr) - 1));

         if (!en_rx) return;
         // reset timeout timer by issuing a rdata read
diff --git a/hw/ip/uart/dv/env/uart_env_pkg.sv b/hw/ip/uart/dv/env/uart_env_pkg.sv
index 21656b0c5a..aa029a01a4 100644
--- a/hw/ip/uart/dv/env/uart_env_pkg.sv
+++ b/hw/ip/uart/dv/env/uart_env_pkg.sv
@@ -37,7 +37,8 @@ package uart_env_pkg;
     RxBreakErr  = 5,
     RxTimeout   = 6,
     RxParityErr = 7,
-    NumUartIntr = 8
+    TxEmpty     = 8,
+    NumUartIntr = 9
   } uart_intr_e;

   // get the number of bytes that triggers watermark interrupt
diff --git a/hw/ip/uart/dv/env/uart_scoreboard.sv b/hw/ip/uart/dv/env/uart_scoreboard.sv
index e36809d1f6..5a39eb64f9 100644
--- a/hw/ip/uart/dv/env/uart_scoreboard.sv
+++ b/hw/ip/uart/dv/env/uart_scoreboard.sv
@@ -141,6 +141,7 @@ class uart_scoreboard extends cip_base_scoreboard #(.CFG_T(uart_env_cfg),
   virtual function void predict_tx_watermark_intr(uint tx_q_size = tx_q.size);
     uint watermark = get_tx_watermark_bytes_by_level(ral.fifo_ctrl.txilvl.get_mirrored_value());
     intr_exp[TxWatermark] = (tx_q_size < watermark) || status_intr_test[TxWatermark];
+    intr_exp[TxEmpty] = (tx_q_size == 0) || status_intr_test[TxEmpty];
   endfunction

   virtual function void predict_rx_watermark_intr(uint rx_q_size = rx_q.size);
@@ -311,6 +312,7 @@ class uart_scoreboard extends cip_base_scoreboard #(.CFG_T(uart_env_cfg),
           // then call the prediction functions for those interrupts to determine the interrupt
           // status.
           status_intr_test[TxWatermark] = item.a_data[TxWatermark];
+          status_intr_test[TxEmpty] = item.a_data[TxEmpty];
           status_intr_test[RxWatermark] = item.a_data[RxWatermark];

           intr_exp |= item.a_data;
@@ -404,6 +406,7 @@ class uart_scoreboard extends cip_base_scoreboard #(.CFG_T(uart_env_cfg),
             // Watermark interrupt state based upon current level of TX/RX fifos. They cannot be
             // cleared by writes to intr_state.
             intr_wdata[TxWatermark] = 1'b0;
