   bit        stop_intr_handler = 1'b0;
   bit        read_all_acq_entries = 1'b0;

+  // Use ACK Control Mode
+  bit        ack_ctrl_en = 1'b0;
+
   // Slow acq process
   bit        slow_acq = 1'b0;

