@@ -14,11 +14,13 @@ class i2c_host_rx_oversample_vseq extends i2c_rx_tx_vseq;
     thigh   == 1;
     t_r     == 1;
     t_f     == 1;
-    thd_sta == 1;
+    thd_sta == 3;
     tsu_sto == 1;
     tsu_dat == 1;
     thd_dat == 1;

+    t_buf > thd_dat + 1;
+
     solve t_r, tsu_dat, thd_dat before tlow;
     solve t_r                   before t_buf;
     solve t_f, thigh            before t_sda_unstable, t_sda_interference;
diff --git a/hw/ip/i2c/dv/env/seq_lib/i2c_target_perf_vseq.sv b/hw/ip/i2c/dv/env/seq_lib/i2c_target_perf_vseq.sv
