+  parameter uint ROM_WORD_ADDR_WIDTH = `ROM_BYTE_ADDR_WIDTH - $clog2(TL_DW / 8);
+  parameter uint ROM_SIZE_BYTES = 2 ** `ROM_BYTE_ADDR_WIDTH;
+  parameter uint ROM_SIZE_WORDS = 2 ** ROM_WORD_ADDR_WIDTH;
