commit 2b8870ccd4666e9f40defe1668fe24bde915d7ba
Author: Pirmin Vogel <vogelpi@lowrisc.org>
Date:   Wed Mar 6 02:00:33 2024 +0100

    [entropy_src] Align enable delay module with fixed CS AES Halt interface

    Previously, the CS AES Halt interface was only active when the SHA3
    engine was performing the final Process operation for which the main SM
    always acknowledges the completion with a done pulse. After fixing
    the interface to always be active when the SHA3 engine is actively
    processing data, the main SM only sends the done pulse for a minority
    of SHA3 operations. This can cause the enable delay module to block
    the re-enablement of the entropy pipeline after disabling as it keeps
    waiting for a done pulse that is never going to arrive.

    This commit fixes this issue by using the sha3_block_processed signal
    instead of the done pulse. This signal is sent by the SHA3 engine
    whenever the processing of a block finishes.

    Signed-off-by: Pirmin Vogel <vogelpi@lowrisc.org>

diff --git a/hw/ip/entropy_src/rtl/entropy_src_core.sv b/hw/ip/entropy_src/rtl/entropy_src_core.sv
index 4e4a81d555..0805b5c275 100644
--- a/hw/ip/entropy_src/rtl/entropy_src_core.sv
+++ b/hw/ip/entropy_src/rtl/entropy_src_core.sv
@@ -634,7 +634,7 @@ module entropy_src_core import entropy_src_pkg::*; #(
     .postht_fifo_not_empty_i(pfifo_postht_not_empty),
     .distr_fifo_not_empty_i(sfifo_distr_not_empty),
     .cs_aes_halt_req_i(cs_aes_halt_req),
-    .sha3_done_i(sha3_done),
+    .sha3_block_processed_i(sha3_block_processed),
     .bypass_mode_i(es_bypass_mode),
     .enable_o(es_delayed_enable)
   );
diff --git a/hw/ip/entropy_src/rtl/entropy_src_enable_delay.sv b/hw/ip/entropy_src/rtl/entropy_src_enable_delay.sv
index 5d8fb3638a..d78aed814e 100644
--- a/hw/ip/entropy_src/rtl/entropy_src_enable_delay.sv
+++ b/hw/ip/entropy_src/rtl/entropy_src_enable_delay.sv
@@ -43,8 +43,8 @@ module entropy_src_enable_delay import prim_mubi_pkg::*; (
   input logic distr_fifo_not_empty_i,

   // SHA3 conditioner inputs
-  input logic   cs_aes_halt_req_i,
-  input mubi4_t sha3_done_i,
+  input logic cs_aes_halt_req_i,
+  input logic sha3_block_processed_i,

   input logic bypass_mode_i,

@@ -64,19 +64,19 @@ module entropy_src_enable_delay import prim_mubi_pkg::*; (
   // Flops
   logic [MaxFifoWait - 1:0] fifo_timer_d, fifo_timer_q;
   logic                     sha3_active_post_en_d, sha3_active_post_en_q;
-  mubi4_t                   sha3_done_q;
+  logic                     sha3_block_processed_q;
   logic                     extend_enable_q;

   always_ff @(posedge clk_i or negedge rst_ni) begin
     if (!rst_ni) begin
       sha3_active_post_en_q   <= 1'b0;
       fifo_timer_q            <= '0;
-      sha3_done_q             <= prim_mubi_pkg::MuBi4False;
+      sha3_block_processed_q  <= 1'b0;
       extend_enable_q         <= 1'b0;
     end else begin
       sha3_active_post_en_q   <= sha3_active_post_en_d;
       fifo_timer_q            <= fifo_timer_d;
-      sha3_done_q             <= sha3_done_i;
+      sha3_block_processed_q  <= sha3_block_processed_i;
       extend_enable_q         <= extend_enable;
     end
   end
@@ -98,10 +98,10 @@ module entropy_src_enable_delay import prim_mubi_pkg::*; (
   // Health checks.
   assign extend_enable = ((fifo_timer_q[0] | data_in_flight) & ~enable_i);

-  // Pulse to extend from the falling edge of the incoming enable pulse
-  // until one cycle after the SHA is done.
+  // Pulse to extend from the falling edge of the incoming enable pulse until one cycle after the
+  // SHA engine has finished processing the current block.
   assign sha3_active_post_en_d = cs_aes_halt_req_i && !enable_i ? 1'b1 :
-                                 mubi4_test_true_strict(sha3_done_q) ? 1'b0 :
+                                 sha3_block_processed_q ? 1'b0 :
                                  sha3_active_post_en_q;

   // Force the output to be low until sha3_active_post_en_q falls or

