rtl_diff:
commit 44badc4df9f077cefd75f6b180a4d161fbb5735e
Author: Adrian Lees <a.lees@lowrisc.org>
Date:   Tue Feb 6 20:49:05 2024 +0000

    [usbdev] Bring up of Av SETUP FIFO

    USBDEV selects between the Av SETUP Buffer and the Av OUT
    Buffer FIFOs based upon the received token packet.
    Reserve the final entry of the Rx FIFO for SETUP packets only,
    ensuring that we may accept the SETUP packet and prevent a
    Control Transfer to Endpoint Zero being retired unsuccessfully
    by the host controller when USBDEV is under heavy load.
    Minimal updates to USBDEV block level DV sequences.

    Signed-off-by: Adrian Lees <a.lees@lowrisc.org>

diff --git a/hw/ip/usbdev/rtl/usbdev.sv b/hw/ip/usbdev/rtl/usbdev.sv
index 54f38469f4..42be4d633f 100644
--- a/hw/ip/usbdev/rtl/usbdev.sv
+++ b/hw/ip/usbdev/rtl/usbdev.sv
@@ -109,6 +109,8 @@ module usbdev
   // RX fifo stores              buf# +  size(0-MaxPktSizeByte)  + EP# + Type
   localparam int RXFifoWidth = NBufWidth + (1+SizeWidth)         +  4  + 1;
   localparam int RXFifoDepth = 8;
+  // derived parameter
+  localparam int RXFifoDepthW = prim_util_pkg::vbits(RXFifoDepth+1);

   usbdev_reg2hw_t reg2hw, reg2hw_regtop;
   usbdev_hw2reg_t hw2reg, hw2reg_regtop;
@@ -227,6 +229,7 @@ module usbdev
   logic              avsetup_rvalid, avsetup_rready;
   logic              avout_rvalid, avout_rready;
   logic              rx_wvalid, rx_wready;
+  logic              rx_wready_setup, rx_wready_out;
   logic              rx_fifo_rvalid;
   logic              rx_fifo_re;

@@ -294,6 +297,17 @@ module usbdev
   assign rx_fifo_re = reg2hw.rxfifo.ep.re | reg2hw.rxfifo.setup.re |
                       reg2hw.rxfifo.size.re | reg2hw.rxfifo.buffer.re;

+  // The number of used entries in the Received Buffer FIFO is presented to the software
+  logic [RXFifoDepthW-1:0] rx_depth;
+  assign hw2reg.usbstat.rx_depth.d = rx_depth;
+
+  // We can always accept a SETUP packet if the Received Buffer FIFO is not full...
+  assign rx_wready_setup = rx_wready;
+  // ... but regular OUT packets are not permitted to use the final entry; still qualified
+  // with 'rx_wready' for when reset is asserted.
+  assign rx_wready_out   = rx_wready & (rx_depth < (RXFifoDepth - 1));
+
+  // Received Buffer FIFO
   prim_fifo_sync #(
     .Width(RXFifoWidth),
     .Pass(1'b0),
@@ -312,7 +326,7 @@ module usbdev
     .rready_i  (rx_fifo_re),
     .rdata_o   (rx_rdata),
     .full_o    (event_rx_full),
-    .depth_o   (hw2reg.usbstat.rx_depth.d),
+    .depth_o   (rx_depth),
     .err_o     ()
   );

@@ -527,7 +541,8 @@ module usbdev
     .avout_rdata_i        (avout_rdata),

     .rx_wvalid_o          (rx_wvalid),
-    .rx_wready_i          (rx_wready),
+    .rx_wready_setup_i    (rx_wready_setup),
+    .rx_wready_out_i      (rx_wready_out),
     .rx_wdata_o           (rx_wdata),
     .setup_received_o     (setup_received),
     .out_endpoint_o       (out_endpoint),  // will be stable for several cycles
diff --git a/hw/ip/usbdev/rtl/usbdev_usbif.sv b/hw/ip/usbdev/rtl/usbdev_usbif.sv
index 5c9c00508d..82d38bec01 100644
--- a/hw/ip/usbdev/rtl/usbdev_usbif.sv
+++ b/hw/ip/usbdev/rtl/usbdev_usbif.sv
@@ -48,7 +48,8 @@ module usbdev_usbif  #(
   input  logic [AVFifoWidth - 1: 0]avout_rdata_i,

   output logic                     rx_wvalid_o,
-  input  logic                     rx_wready_i,
+  input  logic                     rx_wready_setup_i,
+  input  logic                     rx_wready_out_i,
   output logic [RXFifoWidth - 1:0] rx_wdata_o,
   output logic                     setup_received_o,
   output logic [3:0]               out_endpoint_o,
@@ -196,13 +197,25 @@ module usbdev_usbif  #(
     end
   end // always_ff @ (posedge clk_48mhz_i)

+  // select from the appropriate Available Buffer FIFO, SETUP or OUT.
+  logic av_rvalid;
+  logic [AVFifoWidth-1:0] av_rdata;
+  assign av_rvalid = current_setup ? avsetup_rvalid_i : avout_rvalid_i;
+  assign av_rdata  = current_setup ? avsetup_rdata_i  : avout_rdata_i;
+
+  // only SETUP packets are permitted to fill the RxFIFO completely, ensuring that we can always
+  // receive a SETUP packet even under heavy OUT traffic and high software latency.
+  logic rx_wready;
+  assign rx_wready = current_setup ? rx_wready_setup_i : rx_wready_out_i;
+
   // need extra write at end if packet not multiple of 4 bytes
-  assign mem_write_o = avout_rvalid_i & (std_write_q |
+  assign mem_write_o = av_rvalid & (std_write_q |
                        (~out_max_used_q[PktW] & (out_max_used_q[1:0] != 2'b11) & out_ep_acked));
-  assign mem_waddr = {avout_rdata_i, out_max_used_q[PktW-1:2]};
+  assign mem_waddr = {av_rdata, out_max_used_q[PktW-1:2]};
   assign mem_wdata_o = wdata_q;
   assign mem_addr_o = mem_write_o ? mem_waddr : mem_raddr;
   assign mem_req_o = mem_read | mem_write_o;
+  // Is the DATA packet currently being received a SETUP DATA packet or a regular OUT DATA packet?
   assign current_setup = out_ep_setup[out_endpoint_o];

   logic [PktW:0] out_max_minus1;
@@ -213,24 +226,24 @@ module usbdev_usbif  #(
       out_endpoint_o,
       current_setup,
       out_max_minus1,
-      avout_rdata_i
+      av_rdata
   };
   assign rx_wvalid_o = out_ep_acked;
   // Pop the available fifo after the write that used the previous value
   always_ff @(posedge clk_48mhz_i or negedge rst_ni) begin
     if (!rst_ni) begin
-      avout_rready_o <= 1'b0;
+      avsetup_rready_o <= 1'b0;
+      avout_rready_o   <= 1'b0;
     end else begin
-      avout_rready_o <= rx_wvalid_o;
+      avsetup_rready_o <= rx_wvalid_o &  current_setup;
+      avout_rready_o   <= rx_wvalid_o & ~current_setup;
     end
   end
-  // TODO: tie off because Available SETUP Buffer FIFO remains unused
-  assign avsetup_rready_o = 1'b0;

   // full here covers the software blocking by clearing the enable
   assign out_blocked = ~out_ep_setup & ~rx_out_i;
-  // full also covers being blocked because the hardware can't take any transaction
-  assign all_out_blocked = (~rx_wready_i) | (~avout_rvalid_i);
+  // full also covers being blocked because the hardware can't take any transactions at all
+  assign all_out_blocked = (~rx_wready) | (~av_rvalid);

   assign out_ep_full = {NEndpoints{all_out_blocked}} | out_blocked;
   assign out_ep_stall = rx_stall_i;

