commit 60c82fc74b34ba828217c28b9f3ce164fd0e8905
Author: Michael Schaffner <msf@opentitan.org>
Date:   Fri Aug 25 01:04:57 2023 -0700

    [otp_ctrl] Make secret partition LC lock more generic

    This uses the newly created iskeymgr attribute of a partition
    item to determine whether the read/write access to the partition
    has to be modulated with lc_creator_seed_sw_rw_en.

    Signed-off-by: Michael Schaffner <msf@opentitan.org>

diff --git a/hw/ip/otp_ctrl/rtl/otp_ctrl.sv b/hw/ip/otp_ctrl/rtl/otp_ctrl.sv
index 1b54b3afd5..162f04317d 100644
--- a/hw/ip/otp_ctrl/rtl/otp_ctrl.sv
+++ b/hw/ip/otp_ctrl/rtl/otp_ctrl.sv
@@ -309,9 +309,14 @@ module otp_ctrl
     part_access_pre[LifeCycleIdx].write_lock = MuBi8True;
     part_access_pre[LifeCycleIdx].read_lock = MuBi8True;

-    // The SECRET2 partition can only be accessed (write&read) when provisioning is enabled.
+    // Special partitions for keymgr material only become writable when
+    // provisioning is enabled.
     if (lc_ctrl_pkg::lc_tx_test_false_loose(lc_creator_seed_sw_rw_en)) begin
-      part_access_pre[Secret2Idx] = {2{MuBi8True}};
+      for (int k = 0; k < NumPart; k++) begin
+        if (PartInfo[k].iskeymgr) begin
+          part_access_pre[k] = {2{prim_mubi_pkg::MuBi8True}};
+        end
+      end
     end
   end

