commit d15e6bd6d5bb2f464d4795abbb34fac1f4255c6f
Author: Michael Schaffner <msf@opentitan.org>
Date:   Wed Aug 23 19:53:42 2023 -0700

    [otp_ctrl] Ensure broadcast valid is flopped

    Signed-off-by: Michael Schaffner <msf@opentitan.org>

diff --git a/hw/ip/otp_ctrl/rtl/otp_ctrl.sv b/hw/ip/otp_ctrl/rtl/otp_ctrl.sv
index c6cbd5a491..848fab4237 100644
--- a/hw/ip/otp_ctrl/rtl/otp_ctrl.sv
+++ b/hw/ip/otp_ctrl/rtl/otp_ctrl.sv
@@ -1292,7 +1292,22 @@ end
   // Output complete hardware config partition.
   // Actual mapping to other IPs is done via the intersignal topgen feature,
   // selection of fields can be done using the otp_hw_cfg_t struct fields.
-  assign otp_broadcast_o = named_broadcast_assign(part_init_done, part_buf_data);
+  otp_broadcast_t otp_broadcast;
+  assign otp_broadcast = named_broadcast_assign(part_init_done, part_buf_data);
+
+  // Make sure the broadcast valid is flopped before sending it out.
+  lc_ctrl_pkg::lc_tx_t otp_broadcast_valid_q;
+  prim_lc_sender u_prim_lc_sender_otp_broadcast_valid (
+    .clk_i,
+    .rst_ni,
+    .lc_en_i(otp_broadcast.valid),
+    .lc_en_o(otp_broadcast_valid_q)
+  );
+
+  always_comb begin : p_broadcast_valid
+    otp_broadcast_o       = otp_broadcast;
+    otp_broadcast_o.valid = otp_broadcast_valid_q;
+  end

   // Root keys
   logic otp_keymgr_key_valid_d, otp_keymgr_key_valid_q; // need to latch valid

commit 2ba74d6a6113c38efb959561fb60126ab5e53004
Author: Michael Schaffner <msf@opentitan.org>
Date:   Wed Aug 23 18:03:48 2023 -0700

    [otp_ctrl] Fix OOB error in DAI

    We did not hit this corner case before since the OTP array
    was fully populated. The new parameterization is not yet
    fully complete and may not be fully populated, hence we
    should add an OOB check.

    Signed-off-by: Michael Schaffner <msf@opentitan.org>

diff --git a/hw/ip/otp_ctrl/rtl/otp_ctrl_dai.sv b/hw/ip/otp_ctrl/rtl/otp_ctrl_dai.sv
