Author: Michael Schaffner <msf@opentitan.org>
Date:   Tue Aug 8 18:37:46 2023 -0700

    [otp_ctrl] Make CSR read-enables assignment parametric

    Signed-off-by: Michael Schaffner <msf@opentitan.org>

diff --git a/hw/ip/otp_ctrl/rtl/otp_ctrl.sv b/hw/ip/otp_ctrl/rtl/otp_ctrl.sv
index 147ae4e4a6..d802bf1d80 100644
--- a/hw/ip/otp_ctrl/rtl/otp_ctrl.sv
+++ b/hw/ip/otp_ctrl/rtl/otp_ctrl.sv
@@ -299,25 +299,16 @@ module otp_ctrl
   // SEC_CM: ACCESS.CTRL.MUBI
   part_access_t [NumPart-1:0] part_access_pre, part_access;
   always_comb begin : p_access_control
-    // Default (this will be overridden by partition-internal settings).
-    part_access_pre = {{32'(2*NumPart)}{MuBi8False}};
+    // Assigns default and extracts named CSR read enables for SW_CFG partitions.
+    // SEC_CM: PART.MEM.REGREN
+    part_access_pre = named_part_access_pre(reg2hw);
+
     // Permanently lock DAI write and read access to the life cycle partition.
     // The LC partition can only be read from and written to via the LC controller.
     // SEC_CM: LC_PART.MEM.SW_NOACCESS
     part_access_pre[LifeCycleIdx].write_lock = MuBi8True;
     part_access_pre[LifeCycleIdx].read_lock = MuBi8True;

-    // Propagate CSR read enables down to the SW_CFG partitions.
-    // SEC_CM: PART.MEM.REGREN
-    if (!reg2hw.vendor_test_read_lock) begin
-      part_access_pre[VendorTestIdx].read_lock = MuBi8True;
-    end
-    if (!reg2hw.creator_sw_cfg_read_lock) begin
-      part_access_pre[CreatorSwCfgIdx].read_lock = MuBi8True;
-    end
-    if (!reg2hw.owner_sw_cfg_read_lock) begin
-      part_access_pre[OwnerSwCfgIdx].read_lock = MuBi8True;
-    end
     // The SECRET2 partition can only be accessed (write&read) when provisioning is enabled.
     if (lc_ctrl_pkg::lc_tx_test_false_loose(lc_creator_seed_sw_rw_en)) begin
       part_access_pre[Secret2Idx] = {2{MuBi8True}};
diff --git a/hw/ip/otp_ctrl/rtl/otp_ctrl_part_pkg.sv b/hw/ip/otp_ctrl/rtl/otp_ctrl_part_pkg.sv
index 2c359600bb..8f21a63229 100644
--- a/hw/ip/otp_ctrl/rtl/otp_ctrl_part_pkg.sv
+++ b/hw/ip/otp_ctrl/rtl/otp_ctrl_part_pkg.sv
@@ -389,4 +389,25 @@ package otp_ctrl_part_pkg;
     return hw2reg;
   endfunction : named_reg_assign

+  function automatic part_access_t [NumPart-1:0] named_part_access_pre(
+      otp_ctrl_core_reg2hw_t reg2hw);
+    part_access_t [NumPart-1:0] part_access_pre;
+    logic unused_sigs;
+    unused_sigs = ^reg2hw;
+    // Default (this will be overridden by partition-internal settings).
+    part_access_pre = {{32'(2*NumPart)}{prim_mubi_pkg::MuBi8False}};
+    // Note: these could be made a MuBi CSRs in the future.
+    // The main thing that is missing right now is proper support for W0C.
+    if (!reg2hw.vendor_test_read_lock) begin
+      part_access_pre[VendorTestIdx].read_lock = prim_mubi_pkg::MuBi8True;
+    end
+    if (!reg2hw.creator_sw_cfg_read_lock) begin
+      part_access_pre[CreatorSwCfgIdx].read_lock = prim_mubi_pkg::MuBi8True;
+    end
+    if (!reg2hw.owner_sw_cfg_read_lock) begin
+      part_access_pre[OwnerSwCfgIdx].read_lock = prim_mubi_pkg::MuBi8True;
+    end
+    return part_access_pre;
+  endfunction : named_part_access_pre
+
 endpackage : otp_ctrl_part_pkg
diff --git a/hw/ip/otp_ctrl/rtl/otp_ctrl_part_pkg.sv.tpl b/hw/ip/otp_ctrl/rtl/otp_ctrl_part_pkg.sv.tpl
