@@ -1261,6 +1254,9 @@ module i2c_fsm #(
           state_d = StretchTxSetup;
           load_tcount = 1'b1;
           tcount_sel = tSetupData;
+
+          // When leaving stretch state, de-assert software notification
+          event_tx_empty_o = 1'b0;
         end
       end
       StretchTxSetup : begin
