-
-    // Check OTP is locked after fault error.
-    `DV_CHECK_RANDOMIZE_FATAL(this)
-    is_valid_dai_op = 0;
-
-    // Access OTP via DAI interface.
-    dai_wr(dai_addr, wdata0, wdata1);
