commit 5d4d4e522848ee15d5423836cf00c334296a1c45
Author: Michael Schaffner <msf@google.com>
Date:   Wed Jul 27 19:31:45 2022 -0700

    [rom_ctrl] KMAC interface optimization

    As discussed in #12429, the KMAC interface actually supports byte
    strobes. Since the ROM controller only reads out 39bit per cycle,
    it therefore makes sense to only transmit 5 bytes worth of data to KMAC
    per cycle instead of a zero padding to the maximum interface with
    and transferring 8 bytes per cycle.

    This change should improve the ROM hash time by almost 50%.

    Signed-off-by: Michael Schaffner <msf@google.com>

diff --git a/hw/ip/rom_ctrl/dv/env/rom_ctrl_env_pkg.sv b/hw/ip/rom_ctrl/dv/env/rom_ctrl_env_pkg.sv
index 8d862f4991..ed112d7a6f 100644
--- a/hw/ip/rom_ctrl/dv/env/rom_ctrl_env_pkg.sv
+++ b/hw/ip/rom_ctrl/dv/env/rom_ctrl_env_pkg.sv
@@ -34,8 +34,10 @@ package rom_ctrl_env_pkg;
   // KMAC's max digest size is larger than what is required, so declare the size here.
   parameter uint DIGEST_SIZE    = 256;
   parameter uint MAX_CHECK_ADDR = rom_ctrl_reg_pkg::ROM_CTRL_ROM_SIZE - (DIGEST_SIZE / 8);
-  // The data for each line in rom up to the digest is padded out to the kmac message width
-  parameter uint KMAC_DATA_SIZE = MAX_CHECK_ADDR / (TL_DW / 8) * (kmac_pkg::MsgWidth / 8);
+  // The data for each line in rom up to the digest padded to the next byte boundary
+  parameter uint KMAC_DATA_WORD_SIZE = (39 + 7) / 8;
+  parameter uint KMAC_DATA_NUM_WORDS = MAX_CHECK_ADDR / (TL_DW / 8);
+  parameter uint KMAC_DATA_SIZE = KMAC_DATA_NUM_WORDS * KMAC_DATA_WORD_SIZE;
   // The rom width in bits
   parameter uint ROM_MEM_W = 39;

diff --git a/hw/ip/rom_ctrl/dv/env/rom_ctrl_scoreboard.sv b/hw/ip/rom_ctrl/dv/env/rom_ctrl_scoreboard.sv
index ef144d3bb1..c3843552a5 100644
--- a/hw/ip/rom_ctrl/dv/env/rom_ctrl_scoreboard.sv
+++ b/hw/ip/rom_ctrl/dv/env/rom_ctrl_scoreboard.sv
@@ -55,27 +55,27 @@ class rom_ctrl_scoreboard extends cip_base_scoreboard #(

   // Read data sent to the kmac block and check it against memory data
   virtual function void check_kmac_data(const ref byte byte_data_q[$]);
-    int dword = 0;
+    int word = 0;
     int addr = 0;
     // Check that we received the expected amount of data
     `DV_CHECK_EQ(byte_data_q.size(), KMAC_DATA_SIZE, "Unexpected kmac data size")
-    // Read out the data 8 bytes at a time
-    while (dword < byte_data_q.size()) begin
-      bit [kmac_pkg::MsgWidth-1:0] exp, act;
-      bit [ROM_MEM_W-1:0]          mem_data;
+    // Read out the data 5 bytes at a time (one word is 39bit packed into 5 byte)
+    while (word < byte_data_q.size()) begin
+      bit [KMAC_DATA_WORD_SIZE*8-1:0] exp, act;
+      bit [ROM_MEM_W-1:0]             mem_data;
       mem_data = cfg.mem_bkdr_util_h.rom_encrypt_read32(
           addr, RND_CNST_SCR_KEY, RND_CNST_SCR_NONCE, 1'b0);
-      exp = {{kmac_pkg::MsgWidth-ROM_MEM_W{1'b0}}, mem_data};
-      for (int i = 0; i < kmac_pkg::MsgWidth / 8; i++) begin
-        act[i*8+:8] = byte_data_q[dword+i];
+      exp = {{KMAC_DATA_WORD_SIZE*8-ROM_MEM_W{1'b0}}, mem_data};
+      for (int i = 0; i < KMAC_DATA_WORD_SIZE; i++) begin
+        act[i*8+:8] = byte_data_q[word+i];
       end
       // Check the data matches
       `DV_CHECK_EQ(act, exp, $sformatf("Unexpected data at addr: %0x", addr))
       // Check the address is within range
       `DV_CHECK_LT(addr, MAX_CHECK_ADDR,
           $sformatf("Check address out of range: %0x", addr))
-      addr  += (TL_DW / 8);
-      dword += (kmac_pkg::MsgWidth / 8);
+      addr += (TL_DW / 8);
+      word += KMAC_DATA_WORD_SIZE;
     end
   endfunction

