commit 95377d7ea741a4e9ce2a059e9a8e2c0535f3c0e6
Author: Rupert Swarbrick <rswarbrick@lowrisc.org>
Date:   Wed May 11 17:05:07 2022 +0100

    [otbn,rtl] Switch to a level-based req/ack iface between controllers

    Rather than using a single pulse, the controller now holds a
    secure_wipe_req signal high while the secure wipe is running and keeps
    it high until it gets an ack from the start/stop controller.

    Signed-off-by: Rupert Swarbrick <rswarbrick@lowrisc.org>

diff --git a/hw/ip/otbn/rtl/otbn_controller.sv b/hw/ip/otbn/rtl/otbn_controller.sv
index 12b465406e..b2bd1ee186 100644
--- a/hw/ip/otbn/rtl/otbn_controller.sv
+++ b/hw/ip/otbn/rtl/otbn_controller.sv
@@ -137,8 +137,8 @@ module otbn_controller
   input  logic rnd_valid_i,

   // Secure Wipe
-  output logic start_secure_wipe_o,
-  input  logic secure_wipe_done_i,
+  output logic secure_wipe_req_o,
+  input  logic secure_wipe_ack_i,
   input  logic sec_wipe_zero_i,

   input  logic        state_reset_i,
@@ -304,9 +304,11 @@ module otbn_controller

   logic [4:0] insn_bignum_rd_addr_a_q, insn_bignum_rd_addr_b_q, insn_bignum_wr_addr_q;

-  logic secure_wipe_running_q, secure_wipe_running_d;
-  assign secure_wipe_running_d = (start_secure_wipe_o |
-                                  (secure_wipe_running_q & ~secure_wipe_done_i));
+  logic       start_secure_wipe;
+  logic       secure_wipe_running_q, secure_wipe_running_d;
+
+  assign secure_wipe_running_d = start_secure_wipe | (secure_wipe_running_q & ~secure_wipe_ack_i);
+
   always_ff @(posedge clk_i or negedge rst_ni) begin
     if (!rst_ni) begin
       secure_wipe_running_q <= 1'b0;
@@ -314,6 +316,7 @@ module otbn_controller
       secure_wipe_running_q <= secure_wipe_running_d;
     end
   end
+  assign secure_wipe_req_o = start_secure_wipe | secure_wipe_running_q;

   // Stall a cycle on loads to allow load data writeback to happen the following cycle. Stall not
   // required on stores as there is no response to deal with.
@@ -340,8 +343,8 @@ module otbn_controller
   assign executing = (state_q == OtbnStateRun) ||
                      (state_q == OtbnStateStall);

-  assign locking_o = (state_d == OtbnStateLocked) & ~secure_wipe_running_d;
-  assign start_secure_wipe_o = executing & (done_complete | err) & ~secure_wipe_running_q;
+  assign locking_o = (state_d == OtbnStateLocked) & ~secure_wipe_req_o;
+  assign start_secure_wipe = executing & (done_complete | err);

   assign jump_or_branch = (insn_valid_i &
                            (insn_dec_shared_i.branch_insn | insn_dec_shared_i.jump_insn));
diff --git a/hw/ip/otbn/rtl/otbn_core.sv b/hw/ip/otbn/rtl/otbn_core.sv
index cfbdf1afd9..ab19012330 100644
--- a/hw/ip/otbn/rtl/otbn_core.sv
+++ b/hw/ip/otbn/rtl/otbn_core.sv
@@ -223,8 +223,7 @@ module otbn_core
   logic        state_reset;
   logic [31:0] insn_cnt;

-  logic start_secure_wipe;
-  logic secure_wipe_done;
+  logic secure_wipe_req, secure_wipe_ack;

   logic sec_wipe_wdr_d, sec_wipe_wdr_q;
   logic sec_wipe_wdr_urnd_d, sec_wipe_wdr_urnd_q;
@@ -249,7 +248,7 @@ module otbn_core

   core_err_bits_t err_bits_q, err_bits_d;

-  logic start_stop_internal_error;
+  logic start_stop_fatal_error;
   logic rf_bignum_predec_error, alu_bignum_predec_error, ispr_predec_error, mac_bignum_predec_error;
   logic controller_predec_error;
   logic rd_predec_error, predec_error;
@@ -271,8 +270,8 @@ module otbn_core
     .urnd_reseed_ack_i (urnd_reseed_ack),
     .urnd_advance_o    (urnd_advance_start_stop_control),

-    .start_secure_wipe_i (start_secure_wipe),
-    .secure_wipe_done_o  (secure_wipe_done),
+    .secure_wipe_req_i (secure_wipe_req),
+    .secure_wipe_ack_o (secure_wipe_ack),
     .done_o,

     .sec_wipe_wdr_o      (sec_wipe_wdr_d),
@@ -497,9 +496,9 @@ module otbn_core
     .rnd_valid_i       (rnd_valid),

     // Secure wipe
-    .start_secure_wipe_o (start_secure_wipe),
-    .secure_wipe_done_i  (secure_wipe_done),
-    .sec_wipe_zero_i     (sec_wipe_zero),
+    .secure_wipe_req_o (secure_wipe_req),
+    .secure_wipe_ack_i (secure_wipe_ack),
+    .sec_wipe_zero_i   (sec_wipe_zero),

     .state_reset_i(state_reset),
     .insn_cnt_o   (insn_cnt),
@@ -819,7 +818,7 @@ module otbn_core
     .rst_ni,

     .opn_start_i (controller_start),
-    .opn_end_i   (start_secure_wipe),
+    .opn_end_i   (secure_wipe_req),

     .rnd_req_i         (rnd_req),
     .rnd_prefetch_req_i(rnd_prefetch_req),
diff --git a/hw/ip/otbn/rtl/otbn_start_stop_control.sv b/hw/ip/otbn/rtl/otbn_start_stop_control.sv
index c0092faea8..f30cd468c3 100644
--- a/hw/ip/otbn/rtl/otbn_start_stop_control.sv
+++ b/hw/ip/otbn/rtl/otbn_start_stop_control.sv
@@ -38,8 +38,8 @@ module otbn_start_stop_control
   input  logic urnd_reseed_ack_i,
   output logic urnd_advance_o,

-  input   logic start_secure_wipe_i,
-  output  logic secure_wipe_done_o,
+  input   logic secure_wipe_req_i,
+  output  logic secure_wipe_ack_o,
   output  logic done_o,

   output logic       sec_wipe_wdr_o,
@@ -65,7 +65,7 @@ module otbn_start_stop_control
   logic [4:0] addr_cnt_q, addr_cnt_d;

   // There are two ways in which the start/stop controller can be told to stop. Either
-  // start_secure_wipe_i comes from the controller (which means "I've run some instructions and I've
+  // secure_wipe_req_i comes from the controller (which means "I've run some instructions and I've
   // hit an ECALL or error"). Or escalate_en_i can be asserted (which means "Someone else has told
   // us to stop immediately"). If running, both can be true at once.
   //
@@ -75,7 +75,7 @@ module otbn_start_stop_control
   // SEC_CM: CONTROLLER.FSM.GLOBAL_ESC
   logic esc_request, should_lock_d, should_lock_q, stop;
   assign esc_request   = mubi4_test_true_loose(escalate_en_i);
-  assign stop          = esc_request | start_secure_wipe_i;
+  assign stop          = esc_request | secure_wipe_req_i;
   assign should_lock_d = should_lock_q | esc_request;

   always_ff @(posedge clk_i or negedge rst_ni) begin
@@ -104,8 +104,8 @@ module otbn_start_stop_control
     sec_wipe_mod_urnd_o    = 1'b0;
     sec_wipe_zero_o        = 1'b0;
     addr_cnt_inc           = 1'b0;
-    secure_wipe_done_o     = 1'b0;
     fatal_error_o          = 1'b0;
+    secure_wipe_ack_o      = 1'b0;

     unique case (state_q)
       OtbnStartStopStateHalt: begin
@@ -167,11 +167,11 @@ module otbn_start_stop_control
         addr_cnt_inc = 1'b1;
         if (addr_cnt_q == 5'b11111) begin
           state_d = OtbnStartStopSecureWipeComplete;
+          secure_wipe_ack_o = 1'b1;
         end
       end
       OtbnStartStopSecureWipeComplete: begin
         urnd_advance_o = 1'b1;
-        secure_wipe_done_o = 1'b1;
         state_d = should_lock_d ? OtbnStartStopStateLocked : OtbnStartStopStateHalt;
       end
       OtbnStartStopStateLocked: begin
@@ -224,6 +224,6 @@ module otbn_start_stop_control
                       OtbnStartStopStateLocked})

   `ASSERT(StartSecureWipeImpliesRunning_A,
-          start_secure_wipe_i |-> (state_q == OtbnStartStopStateRunning))
+          $rose(secure_wipe_req_i) |-> (state_q == OtbnStartStopStateRunning))

 endmodule

