commit c941279301af2774f8d64120e31466a55669ed25
Author: Timothy Chen <timothytim@google.com>
Date:   Wed Jun 1 14:19:15 2022 -0700

    [pwrmgr] Fix escalate request CDC

    - addresses #12981
    - If the escalate request is not permanent, it is possible
      for the pwrmgr to miss this request since it goes through
      an always-on clock synchronization.
    - capture and hold escalate request until the system resets.

    Signed-off-by: Timothy Chen <timothytim@google.com>

diff --git a/hw/ip/pwrmgr/rtl/pwrmgr.sv b/hw/ip/pwrmgr/rtl/pwrmgr.sv
index e0506a4745..e23ad4669a 100644
--- a/hw/ip/pwrmgr/rtl/pwrmgr.sv
+++ b/hw/ip/pwrmgr/rtl/pwrmgr.sv
@@ -104,19 +104,27 @@ module pwrmgr
     .clk_o(rst_esc_n)
   );

-  logic esc_rst_req;
-
+  logic esc_rst_req_d, esc_rst_req_q;
   prim_esc_receiver #(
     .N_ESC_SEV   (alert_handler_reg_pkg::N_ESC_SEV),
     .PING_CNT_DW (alert_handler_reg_pkg::PING_CNT_DW)
   ) u_esc_rx (
     .clk_i(clk_esc),
     .rst_ni(rst_esc_n),
-    .esc_req_o(esc_rst_req),
+    .esc_req_o(esc_rst_req_d),
     .esc_rx_o(esc_rst_rx_o),
     .esc_tx_i(esc_rst_tx_i)
