@@ -266,8 +266,8 @@ module otbn_core
     .urnd_reseed_ack_i (urnd_reseed_ack),
     .urnd_advance_o    (urnd_advance_start_stop_control),

-    .start_secure_wipe_i  (start_secure_wipe),
