+  if (rtl_started_) {
+    if (!trace_entry.is_compatible(rtl_entry_)) {
       std::cerr
-          << ("ERROR: Execution trace entry doesn't match stall:\n"
-              "  Stall entry was:\n");
-      rtl_stalled_entry_.print("    ", std::cerr);
-      std::cerr << "  Execution entry was:\n";
