+  import prim_mubi_pkg::mubi8_test_false_loose;
+
   ////////////////////////
   // Integration Checks //
   ////////////////////////
@@ -253,8 +258,8 @@ module lc_ctrl
   logic          otp_prog_error_d, fatal_prog_error_q;
   logic          state_invalid_error_d, fatal_state_error_q;
