+        // `esc_req_out` signal.
         main_clk.wait_clks(TIMEOUT_CYCLES + 1);
-        if (esc_en != 1) test_error("Design failed to detect ping request timeout!");
+        if (esc_req_out != 1) test_error("Design failed to detect ping request timeout!");
       end
