+          cfg.clk_rst_vif.wait_clks(1);
+          if (checked_kmac_cmd == CmdDone) begin
+            checked_kmac_cmd = CmdNone;
+          end
+          ,
+          wait(cfg.under_reset);
+      )
+    end
