-
-  // wkup_thold
-  assign wkup_thold_reg_wr  = aon_reg2hw.wkup_thold.qe;
-  assign wkup_thold_wr_data = aon_reg2hw.wkup_thold.q;
-
-  // wkup_count
-  assign wkup_count_reg_wr  = aon_reg2hw.wkup_count.qe;
-  assign wkup_count_wr_data = aon_reg2hw.wkup_count.q;
