+static std::string wlen_val_to_hex_str(uint32_t val[8]) {
+  std::ostringstream oss;
+
+  oss << std::hex << "0x";
+  for (int i = 7; i >= 0; --i) {
+    oss << std::setfill('0') << std::setw(8) << val[i];
+  }
+
+  return oss.str();
+}
