commit e2301212c5da7fd82f27f5ed1e58775406249a8c
Author: Rupert Swarbrick <rswarbrick@lowrisc.org>
Date:   Tue Mar 16 08:09:11 2021 +0000

    [otbn] Integrate ECC check bits properly into the memory

    These extra bits will be used for ECC-based integrity checks. We're
    not doing that as yet, but want correctly sized memories for area
    estimation.

    We'd already expanded the memories, using the top bits as check bits.
    Unfortunately, that causes (correctly) Verilator lint errors. Most are
    easy enough to waive with unused_foo signals, but our choice of a
    write mask doesn't divide into the memory size which causes warnings
    in the SRAM primitive.

    Rather than hack around further, this patch integrates things more
    properly, putting 7 (ignored) "check bits" after each 32-bit word in
    the data memory. For now, otbn.sv converts between the expanded
    312-bit words and the narrow 256-bit words that the SRAM adapter, the
    core and the model expect. Once we start generating/consuming
    integrity properly, this conversion will essentially move to the Ibex
    and OTBN ALUs.

    As well as the narrowing/widening conversions in otbn.sv (repeated in
    otbn_top_sim.sv), we also use the new Ecc32MemArea class to handle the
    check bit insertion.

    Signed-off-by: Rupert Swarbrick <rswarbrick@lowrisc.org>

diff --git a/hw/ip/otbn/rtl/otbn.sv b/hw/ip/otbn/rtl/otbn.sv
index 2088252ec9..fe7c9a9967 100644
--- a/hw/ip/otbn/rtl/otbn.sv
+++ b/hw/ip/otbn/rtl/otbn.sv
@@ -146,15 +146,15 @@ module otbn
   prim_ram_1p_adv #(
     .Width           (39),
     .Depth           (ImemSizeWords),
-    .DataBitsPerMask (32) // Write masks are not supported.
+    .DataBitsPerMask (39) // Write masks are not supported.
   ) u_imem (
     .clk_i,
     .rst_ni,
     .req_i    (imem_req),
     .write_i  (imem_write),
     .addr_i   (imem_index),
-    .wdata_i  (39'(imem_wdata)),
-    .wmask_i  (39'(imem_wmask)),
+    .wdata_i  ({7'd0, imem_wdata}),
+    .wmask_i  ({{7{imem_wmask[0]}}, imem_wmask}),
     .rdata_o  (imem_rdata),
     .rvalid_o (imem_rvalid),
     .rerror_o (imem_rerror_vec),
@@ -234,6 +234,10 @@ module otbn
   assign imem_rerror_bus  = !imem_access_core ? {imem_rerror, 1'b0} : 2'b00;
   assign imem_rerror_core = imem_rerror;

+  // The top bits of IMEM rdata aren't currently used (they will eventually be used for integrity
+  // checks both on the bus and within the core)
+  logic unused_imem_top_rdata;
+  assign unused_imem_top_rdata = &{1'b0, imem_rdata[38:32]};

   // Data Memory (DMEM) ========================================================

@@ -246,9 +250,9 @@ module otbn
   logic dmem_req;
   logic dmem_write;
   logic [DmemIndexWidth-1:0] dmem_index;
-  logic [WLEN-1:0] dmem_wdata;
-  logic [WLEN-1:0] dmem_wmask;
-  logic [(WLEN+7*8)-1:0] dmem_rdata;
+  logic [ExtWLEN-1:0] dmem_wdata;
+  logic [ExtWLEN-1:0] dmem_wmask;
+  logic [ExtWLEN-1:0] dmem_rdata;
   logic dmem_rvalid;
   logic [1:0] dmem_rerror_vec;
   logic dmem_rerror;
@@ -256,18 +260,24 @@ module otbn
   logic dmem_req_core;
   logic dmem_write_core;
   logic [DmemIndexWidth-1:0] dmem_index_core;
-  logic [WLEN-1:0] dmem_wdata_core;
-  logic [WLEN-1:0] dmem_wmask_core;
-  logic [WLEN-1:0] dmem_rdata_core;
+  logic [WLEN-1:0] dmem_wdata_core_nointeg;
+  logic [WLEN-1:0] dmem_wmask_core_nointeg;
+  logic [WLEN-1:0] dmem_rdata_core_nointeg;
+  logic [ExtWLEN-1:0] dmem_wdata_core;
+  logic [ExtWLEN-1:0] dmem_wmask_core;
+  logic [ExtWLEN-1:0] dmem_rdata_core;
   logic dmem_rvalid_core;
   logic dmem_rerror_core;

   logic dmem_req_bus;
   logic dmem_write_bus;
