+      fatal_macro_error_q <= '0;
+      fatal_check_error_q <= '0;
     end else begin
-      otp_macro_failure_q <= otp_macro_failure_d;
-      otp_check_failure_q <= otp_check_failure_d;
+      fatal_macro_error_q <= fatal_macro_error_d;
+      fatal_check_error_q <= fatal_check_error_d;
     end
   end

